// ═══ THE TRAP: VTs don't help if DB is the bottleneck ═══

// Before VTs: 200 platform threads, 100 DB connections → 100 concurrent queries
// After VTs:  200,000 virtual threads, 100 DB connections → STILL 100 concurrent queries!
// Result: 199,900 VTs blocking on connection pool → same throughput, more memory!

// ═══ CORRECT: VTs + Semaphore + Timeout ═══
Semaphore dbGate = new Semaphore(100);

try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    executor.submit(() -> {
        // Timeout: don't wait forever for a DB permit
        if (!dbGate.tryAcquire(5, TimeUnit.SECONDS)) {
            throw new TimeoutException("DB pool exhausted — backpressure!");
        }
        try {
            return jdbcTemplate.queryForObject("SELECT balance FROM accounts WHERE id = ?",
                BigDecimal.class, accountId);
        } finally {
            dbGate.release();
        }
    });
}

// ═══ WHEN VTs ACTUALLY HELP ═══
// Scenario: web server with 10K concurrent HTTP requests, each doing:
//   1. Call external API (200ms I/O wait)
//   2. Query DB (50ms I/O wait)
//   3. Compute response (1ms CPU)
// Platform threads: 200 threads → 200 concurrent requests → 10K takes 10 seconds
// Virtual threads: 10K VTs → 10K concurrent requests → all complete in ~250ms!
// VTs help because the BOTTLENECK was thread count, not DB or API.
