// File: src/test/java/com/bank/java8/CapacityTest.java
package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class CapacityTest {

    // Effective capacity is the MINIMUM of the real limiting resources,
    // not the number of (cheap, unlimited) virtual threads.
    int effectiveCapacity(int dbConnections, int cpuCores, int rateLimitPerSec) {
        return Math.min(dbConnections, Math.min(cpuCores, rateLimitPerSec));
    }

    @Test
    void virtualThreadsDoNotRaiseRealLimits() {
        // 50_000 virtual threads, but DB pool=100, cores=8, rate=500
        int capacity = effectiveCapacity(100, 8, 500);
        assertThat(capacity).isEqualTo(8);   // bounded by CPU cores here
    }
}
